def solve_g_n():
    N_max = 4000
    g = {}
    solutions = []

    # Base case
    g[1] = 1

    # Helper function to check primality (simple trial division for this range)
    def is_prime(k):
        if k <= 1:
            return False
        if k <= 3:
            return True
        if k % 2 == 0 or k % 3 == 0:
            return False
        i = 5
        while i * i <= k:
            if k % i == 0 or k % (i + 2) == 0:
                return False
            i += 6
        return True

    # Iterate from 2 up to N_max
    for n in range(2, N_max + 1):
        if is_prime(n):
            # Condition (i)
            g[n] = n + 1
        else:
            # Composite number n. Find the smallest prime factor p.
            p = -1
            for i in range(2, int(n**0.5) + 1):
                if n % i == 0:
                    p = i
                    break
            if p == -1: # Should not happen if n is composite and > 1
                p = n # Safety check, if somehow missed finding a factor

            k = n // p

            # Recurrence relation derived from (ii):
            # g(n) = p * g(n/p) + (n/p) * (p + 1) - n
            # g(n) = p * g(k) + k * (p + 1) - n

            # Since k < n, g[k] must already be computed
            if k not in g:
                # This should only happen if the smallest prime factor logic failed or if n is prime (handled above)
                raise Exception(f"g({k}) not computed for n={n}")

            g[n] = p * g[k] + k * (p + 1) - n

        # Check the condition g(n) = 2n
        if g[n] == 2 * n:
            solutions.append(n)

    return solutions

solutions = solve_g_n()
print("Solutions found (n <= 4000):", solutions)

